VIVO_MODEL_COLS = ["VIVO Y05 4G 4/64GB", "VIVO Y05 4G 4/128GB", "VIVO Y11D 4G 4/128GB", "VIVO Y31D 4G 6/128GB", "VIVO Y31D 4G 6/256GB"]
VIVO_COMPANY_UNLOCK_TARGET = 2160  # company-wide units that must be hit before ANY AM can win a voucher
VIVO_AM_ELIGIBILITY_PCT = 1.0      # an AM only competes once their own Area clears 100% of its target
VIVO_PERIOD_LABEL = "1-31 Oct 2026"
