def export_vivo_gameplan(target_xlsx_path, tsm_df, area_to_region=None):
    """Reads the Vivo target file ('target shop' sheet: one row per shop
    with a target for each of the 5 Y05/Y11D/Y31D sub-models) and
    matches it against actual October HANDSET sales of those exact
    CUSTOM_SUBMODEL values. The sheet's own 'REGION' column is actually
    an Area name and 'ZONE_AREA' a coarse BMA/UPC split -- to stay
    consistent with the rest of the dashboard (which uses 3 regions:
    BMA / UPC I / UPC II) the real region is looked up via
    `area_to_region` instead of trusting either of those columns.
    Returns ([], [], {}) if the file isn't found."""
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return [], [], {}

    target_df = pd.read_excel(target_xlsx_path, sheet_name="target shop")
    target_df = target_df.dropna(subset=["SHOP_CODE"]).copy()
    target_df["SHOP_CODE"] = pd.to_numeric(target_df["SHOP_CODE"], errors="coerce").astype("Int64")

    h = tsm_df[(tsm_df["CUSTOM_PRODGROUP"] == "HANDSET") & (tsm_df["CUSTOM_SUBMODEL"].isin(VIVO_MODEL_COLS))].copy()
    h["SHOP_CODE"] = pd.to_numeric(h["SHOP_CODE"], errors="coerce").astype("Int64")
    h["DATE"] = pd.to_datetime(h["DATE"])

    daily = h.groupby(h["DATE"].dt.strftime("%Y-%m-%d"))["QTY"].sum().reset_index()
    daily_actual = [{"date": r["DATE"], "qty": int(r["QTY"])} for _, r in daily.iterrows()]

    per_shop_model = h.groupby(["SHOP_CODE", "CUSTOM_SUBMODEL"])["QTY"].sum()
    per_shop_total = h.groupby("SHOP_CODE")["QTY"].sum().to_dict()

    gdd = h.groupby(["SHOP_CODE", "CUSTOM_SUBMODEL", h["DATE"].dt.strftime("%Y-%m-%d")])["QTY"].sum()
    daily_detail = [
        {"code": int(sc), "model": model, "date": date, "qty": int(q)}
        for (sc, model, date), q in gdd.items()
    ]

    shop_records = []
    for _, r in target_df.iterrows():
        code = int(r["SHOP_CODE"])
        area = r["REGION"]  # sheet's "REGION" column is actually the Area name
        region = (area_to_region or {}).get(area, r.get("ZONE_AREA", ""))
        target_total = float(r["Grand Total"])
        actual_total = int(per_shop_total.get(code, 0))
        targets_by_model = {m: float(r[m]) for m in VIVO_MODEL_COLS}
        actuals_by_model = {m: int(per_shop_model.get((code, m), 0)) for m in VIVO_MODEL_COLS}
        shop_records.append({
            "area": area,
            "region": region,
            "am": str(r["AM"]).strip(),
            "code": code,
            "shop": str(r["SHOP_NAME"]).strip(),
            "targetTotal": round(target_total, 2),
            "actualTotal": actual_total,
            "targetsByModel": targets_by_model,
            "actualsByModel": actuals_by_model,
        })
    return shop_records, daily_actual, daily_detail

# ---------------------------------------------------------------------
# Huawei Watch GT7 -- EDIT HERE if the target file changes.
# ---------------------------------------------------------------------
# Which column of the target sheet ("Sheet1") holds the Huawei Watch GT7 target.
# The FIRST name found in the sheet is used, so a file that carries both a
# newer "TG New" column and the older "TG Huawei GT7" column reads the newer one.
# Reorder / edit this list if the target file's layout changes. Other sheets
# in the workbook (e.g. a working "Sheet2") are ignored.
GT7_TARGET_COLUMNS = ["TG New", "TG Huawei GT7"]
GT7_NOV_TARGET_RATIO = 0.5   # Nov target per shop = 50% of its Oct target (Oct + Nov are shown together)

def parse_gt7_variant(desc):
    """'ACC,HUAWEI,WATCH,GT7 PRO 46MM,GREEN' -> ('GT7 PRO', '46MM', 'Green').
    Model = GT7 or GT7 PRO; size = the NNMM token; colour = whatever follows
    the model/size field (e.g. 'WHITE LEATHER' -> 'White Leather')."""
    d = str(desc).upper()
    model = "GT7 PRO" if re.search(r"GT7\s*PRO", d) else "GT7"
    m = re.search(r"(\d{2})\s*MM", d)
    size = (m.group(1) + "MM") if m else "-"
    parts = [p.strip() for p in d.split(",")]
    idx = next((i for i, p in enumerate(parts) if "GT7" in p), None)
    color = ", ".join(parts[idx + 1:]) if idx is not None and idx + 1 < len(parts) else ""
    return model, size, (color.title() if color else "-")

def export_huawei_watch_gt7(target_xlsx_path, tsm_df, area_to_region=None):
    """Reads Target_Watch_GT7.xlsx ('Sheet1': one row per shop with a
    target for Huawei Watch GT7, in the column chosen by GT7_TARGET_COLUMNS) and matches it against actual October
    sales where DESCRIPTION contains HUAWEI, WATCH and GT7 (this covers
    both the base GT7 and the GT7 PRO line, since 'PRO' models'
    descriptions still contain the substring 'GT7'). Only 80 of 243
    shops have a target set this period; the rest are kept in the
    shop universe with target=0 rather than dropped, so Actual still
    shows if one of them sells a unit anyway. Returns (shops, daily, variants);
    all three are empty lists if the file isn't found."""
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return [], [], []

    target_df = pd.read_excel(target_xlsx_path, sheet_name="Sheet1")
    target_df = target_df.dropna(subset=["SHOP_CODE"]).copy()
    target_df["SHOP_CODE"] = pd.to_numeric(target_df["SHOP_CODE"], errors="coerce").astype("Int64")

    target_col = next((c for c in GT7_TARGET_COLUMNS if c in target_df.columns), None)
    if target_col is None:
        raise ValueError(f"Huawei Watch GT7 target file has none of the expected target columns {GT7_TARGET_COLUMNS}; found {list(target_df.columns)}")
    for c in GT7_TARGET_COLUMNS:
        if c in target_df.columns:
            target_df[c] = pd.to_numeric(target_df[c], errors="coerce").fillna(0)
    print(f"    Huawei Watch GT7 target column used: '{target_col}' (total {target_df[target_col].sum():,.0f})")
    # If the sheet carries other candidate columns, say how the choice differs so a
    # stale/leftover column can't silently change which shops have a target.
    for other in GT7_TARGET_COLUMNS:
        if other != target_col and other in target_df.columns:
            lost = int(((target_df[other] > 0) & (target_df[target_col] <= 0)).sum())
            gained = int(((target_df[other] <= 0) & (target_df[target_col] > 0)).sum())
            msg = f"vs '{other}' (total {target_df[other].sum():,.0f}): {gained} shops gain a target, {lost} lose one"
            print(f"      {'WARNING ' if (lost or gained) else ''}{msg}")

    desc = tsm_df["DESCRIPTION"].astype(str).str.upper()
    mask = desc.str.contains("HUAWEI") & desc.str.contains("WATCH") & desc.str.contains("GT7")
    h = tsm_df[mask].copy()
    h["SHOP_CODE"] = pd.to_numeric(h["SHOP_CODE"], errors="coerce").astype("Int64")
    h["DATE"] = pd.to_datetime(h["DATE"])

    # One entry per calendar day from the 1st of the month through the last day in
    # the TSM file -- INCLUDING days with zero GT7 sales. The tab's Run Rate uses
    # len(daily) as "days elapsed", so a quiet day must not silently drop out.
    last_day = pd.to_datetime(tsm_df["DATE"]).max().normalize()
    first_day = pd.to_datetime(tsm_df["DATE"]).min().normalize().replace(day=1)   # tab spans Oct + Nov (cumulative)
    all_days = pd.date_range(first_day, last_day, freq="D")
    by_day = h.groupby(h["DATE"].dt.normalize())["QTY"].sum().reindex(all_days, fill_value=0)
    daily_actual = [{"date": d.strftime("%Y-%m-%d"), "qty": int(q)} for d, q in by_day.items()]

    per_shop = h.groupby("SHOP_CODE")["QTY"].sum().to_dict()

    shop_records = []
    for _, r in target_df.iterrows():
        code = int(r["SHOP_CODE"])
        area = r["Area"] if pd.notna(r["Area"]) else ""
        region = r["Region"] if pd.notna(r["Region"]) else (area_to_region or {}).get(area, "")
        shop_records.append({
            "area": area,
            "region": region,
            "type": r["SHOP_TYPE"],
            "code": code,
            "shop": str(r["SHOP_NAME"]).strip(),
            # Cumulative Oct + Nov target: every shop gets Nov = 50% of its Oct target, counted on top of Oct.
            "target": float(r[target_col]) * (1 + GT7_NOV_TARGET_RATIO),
            "targetOct": float(r[target_col]),
            "targetNov": float(r[target_col]) * GT7_NOV_TARGET_RATIO,
            "actual": int(per_shop.get(code, 0)),
        })
    # Variant detail (model / size / colour per shop), so the tab can show the
    # GT7 vs GT7 PRO split and which size+colour sold how many -- and keep
    # honouring the Region/Type/Area/Shop filters. Restricted to shops in the
    # target file so it always ties out to the KPI totals.
    shop_codes = set(int(c) for c in target_df["SHOP_CODE"].dropna())
    vagg = {}
    dropped = 0
    for _, r in h.iterrows():
        code = r["SHOP_CODE"]
        qty = int(r["QTY"]) if pd.notna(r["QTY"]) else 0
        if pd.isna(code) or int(code) not in shop_codes:
            dropped += qty
            continue
        model, size, color = parse_gt7_variant(r["DESCRIPTION"])
        key = (int(code), model, size, color)
        vagg[key] = vagg.get(key, 0) + qty
    if dropped:
        print(f"    WARNING Huawei Watch GT7: {dropped} units sold in shops missing from the target file are not shown")
    variant_records = [
        {"code": k[0], "model": k[1], "size": k[2], "color": k[3], "qty": q}
        for k, q in sorted(vagg.items()) if q
    ]
    return shop_records, daily_actual, variant_records

RENO16_PATTERN = r"RENO\s?16"   # Reno 16, Reno 16F, Reno 16 Pro ... (not Reno 13/14/15)

def parse_reno16_variant(desc):
    """'H/S,OPPO,RENO16F,5G,8/256,POP WHITE' -> ('Reno 16F', '8/256GB', 'POP WHITE')."""
    parts = [p.strip() for p in str(desc).split(",")]
    model_raw = parts[2].upper() if len(parts) > 2 else ""
    m = re.match(r"RENO\s?16\s*([A-Z]*)", model_raw)
    suffix = m.group(1) if m else ""
    model = "Reno 16" + (suffix if len(suffix) == 1 else (" " + suffix if suffix else ""))   # Reno 16F, Reno 16 PRO
    size = parts[4] if len(parts) > 4 else "-"
    if re.fullmatch(r"\d+/\d+", size):
        size += "GB"
    color = re.sub(r"\s+", " ", parts[5]) if len(parts) > 5 else "-"
    # sales data spells one colour both "TWILIGHT VIOLET" and "TWILIGHTVIOLET"
    color = color.replace("TWILIGHTVIOLET", "TWILIGHT VIOLET")
    return model, size, color

def export_oppo_reno16(target_xlsx_path, tsm_df, shop_lookup, area_to_region=None):
    """OPPO Reno 16 Series game plan (October 2026).
    Target file: sheet 'Target Allocation' (one row per shop: PC flag, Target OCT,
    '80% Achieve' threshold) and 'Sheet1' (RRH -> AM -> Area mapping).
    Actuals: TSM rows whose DESCRIPTION matches Reno 16 / 16F / 16 Pro, counted
    from the 1st of the month. Shops that sold a Reno 16 but are not in the
    target file are kept as Non-PC shops (target 0) so their units and their
    Non-PC incentive are not lost.
    Returns (shops, daily, variants, org) -- all empty if the file is missing."""
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return [], [], [], []

    t = pd.read_excel(target_xlsx_path, sheet_name="Target Allocation", header=2)
    t = t[pd.to_numeric(t["Shop Code"], errors="coerce").notna()].copy()
    t["Shop Code"] = pd.to_numeric(t["Shop Code"]).astype(int)

    org_df = pd.read_excel(target_xlsx_path, sheet_name="Sheet1", header=1)
    org_df = org_df[org_df["Area WW"].notna() & ~org_df["RRH"].astype(str).str.strip().str.lower().eq("total") & ~org_df["Area WW"].astype(str).str.strip().str.lower().eq("total")].copy()
    org_df["RRH"] = org_df["RRH"].ffill()
    org_df["Am"] = org_df["Am"].ffill()
    org = [{"rrh": str(r["RRH"]).strip(), "am": str(r["Am"]).strip(), "area": str(r["Area WW"]).strip()} for _, r in org_df.iterrows()]
    area_org = {o["area"]: o for o in org}

    desc = tsm_df["DESCRIPTION"].astype(str).str.upper()
    h = tsm_df[desc.str.contains(RENO16_PATTERN, regex=True)].copy()
    h["SHOP_CODE"] = pd.to_numeric(h["SHOP_CODE"], errors="coerce")
    h = h.dropna(subset=["SHOP_CODE"])
    h["SHOP_CODE"] = h["SHOP_CODE"].astype(int)
    h["DATE"] = pd.to_datetime(h["DATE"])

    last_day = pd.to_datetime(tsm_df["DATE"]).max().normalize()
    all_days = pd.date_range(last_day.replace(day=1), last_day, freq="D")
    by_day = h.groupby(h["DATE"].dt.normalize())["QTY"].sum().reindex(all_days, fill_value=0)
    daily = [{"date": d.strftime("%Y-%m-%d"), "qty": int(q)} for d, q in by_day.items()]

    per_shop = h.groupby("SHOP_CODE")["QTY"].sum().to_dict()
    tsm_area = h.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")["AREA"].to_dict()

    def info(code):
        return shop_lookup.get(str(code), {})

    shops = []
    for _, r in t.iterrows():
        code = int(r["Shop Code"])
        i = info(code)
        area = str(r["Area WW"]).strip()
        if area not in area_org:                    # e.g. the one shop filed under 'WW'
            area = i.get("area") or tsm_area.get(code) or area
        o = area_org.get(area, {})
        shops.append({
            "code": code, "shop": str(r["Store Name"]).strip(),
            "area": area, "region": i.get("region") or (area_to_region or {}).get(area, ""),
            "type": i.get("type") or "",
            "rrh": o.get("rrh", ""), "am": o.get("am", ""),
            "pc": int(r["PC"]), "target": int(r["Target OCT"]), "thresh": int(r["80% Achieve"]),
            "sepSellout": int(r["Sep Sell-out 16 Series"]), "stock": int(r["Total Stock 16 Series"]),
            "actual": int(per_shop.get(code, 0)),
        })
    in_file = {s["code"] for s in shops}
    extra = 0
    for code, q in per_shop.items():
        if code in in_file:
            continue
        i = info(code); area = i.get("area") or tsm_area.get(code) or ""
        o = area_org.get(area, {})
        shops.append({
            "code": int(code), "shop": i.get("shop") or str(code), "area": area,
            "region": i.get("region") or (area_to_region or {}).get(area, ""), "type": i.get("type") or "",
            "rrh": o.get("rrh", ""), "am": o.get("am", ""),
            "pc": 0, "target": 0, "thresh": 0, "sepSellout": 0, "stock": 0, "actual": int(q),
        })
        extra += int(q)
    if extra:
        print(f"    OPPO Reno 16: {extra} units sold in {len(shops)-len(in_file)} shops that are not in the target file (treated as Non-PC, target 0)")

    vagg = {}
    for _, r in h.iterrows():
        qty = int(r["QTY"]) if pd.notna(r["QTY"]) else 0
        model, size, color = parse_reno16_variant(r["DESCRIPTION"])
        key = (int(r["SHOP_CODE"]), model, size, color)
        vagg[key] = vagg.get(key, 0) + qty
    variants = [{"code": k[0], "model": k[1], "size": k[2], "color": k[3], "qty": q} for k, q in sorted(vagg.items()) if q]
    return shops, daily, variants, org

_THAI_RE = re.compile("[\u0e00-\u0e7f]")

def build_thai_name_map(tsm_df, contest_xlsx_path=None):
    """SALE_CODE -> Thai-only display name. The same salesperson can appear in
    TSM under a Thai spelling in some rows and an English spelling in others;
    we keep the most frequent Thai spelling for the code (across the whole TSM
    file), then fall back to the Mongkol roster (Thai names by Sales ID).
    Codes with no Thai spelling anywhere keep their only (English) name."""
    d = tsm_df[["SALE_CODE", "SALE_NAME"]].dropna().copy()
    d["SALE_CODE"] = d["SALE_CODE"].astype(str).str.strip()
    d["SALE_NAME"] = d["SALE_NAME"].astype(str).str.strip()
    is_th = d["SALE_NAME"].map(lambda x: bool(_THAI_RE.search(x)))
    mp = {}
    for code, grp in d[is_th].groupby("SALE_CODE"):
        mp[code] = grp["SALE_NAME"].value_counts().index[0]
    if contest_xlsx_path and os.path.exists(contest_xlsx_path):
        try:
            m = pd.read_excel(contest_xlsx_path, sheet_name="รายชื่อผู้เข้าร่วมการแข่งขัน", header=3)
            for _, r in m.dropna(subset=["Sales ID", "Sale Name"]).iterrows():
                sid = str(r["Sales ID"]).strip(); nm = str(r["Sale Name"]).strip()
                if sid not in mp and _THAI_RE.search(nm):
                    mp[sid] = nm
        except Exception:
            pass
    other = {}
    for code, grp in d[~is_th].groupby("SALE_CODE"):
        if code not in mp:
            other[code] = grp["SALE_NAME"].value_counts().index[0]
    return mp, other

def export_true_mobile_care(target_xlsx_path, tsm_df, shop_lookup, area_to_region=None, contest_xlsx_path=None, individual_xlsx_path=None):
    """True Mobile Care tab. Target = per-shop 'Target QTY_True Mobile Care' from the
    target file; Actual = TSM column 'Flag TrueMobileCare' (col AW; 1 = a TMC
    plan sold with the order line) x QTY, counted from the 1st of the month.
    Sales-level rows are keyed by (SALE_CODE, shop) and use a Thai-only name.
    Returns dict(shops, daily, sales, meta)."""
    empty = {"shops": [], "daily": [], "sales": [], "meta": {}}
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return empty
    t = pd.read_excel(target_xlsx_path)
    tcol = [c for c in t.columns if "Target" in str(c)][0]
    t = t[pd.to_numeric(t["SHOP_WW"], errors="coerce").notna()].copy()
    t["SHOP_WW"] = pd.to_numeric(t["SHOP_WW"]).astype(int)

    f = tsm_df[pd.to_numeric(tsm_df["Flag TrueMobileCare"], errors="coerce").fillna(0) > 0].copy()
    f["SHOP_CODE"] = pd.to_numeric(f["SHOP_CODE"], errors="coerce")
    f = f.dropna(subset=["SHOP_CODE"]); f["SHOP_CODE"] = f["SHOP_CODE"].astype(int)
    f["DATE"] = pd.to_datetime(f["DATE"])
    f["QTY"] = pd.to_numeric(f["QTY"], errors="coerce").fillna(0)

    last_day = pd.to_datetime(tsm_df["DATE"]).max().normalize()
    all_days = pd.date_range(last_day.replace(day=1), last_day, freq="D")
    by_day = f.groupby(f["DATE"].dt.normalize())["QTY"].sum().reindex(all_days, fill_value=0)
    daily = [{"date": d.strftime("%Y-%m-%d"), "qty": int(q)} for d, q in by_day.items()]

    per_shop = f.groupby("SHOP_CODE")["QTY"].sum().to_dict()
    tsm_info = tsm_df.assign(_c=pd.to_numeric(tsm_df["SHOP_CODE"], errors="coerce")).dropna(subset=["_c"]).drop_duplicates("_c")
    tsm_info = {int(r["_c"]): r for _, r in tsm_info.iterrows()}

    def info(code):
        i = dict(shop_lookup.get(str(code), {}))
        r = tsm_info.get(code)
        if r is not None:
            i.setdefault("shop", str(r["SHOP NAME"]).strip()); i.setdefault("area", r["AREA"])
            i.setdefault("region", r["REGION"]); i.setdefault("type", r["TYPE SHOP"])
        return i

    shops, seen = [], set()
    for _, r in t.iterrows():
        code = int(r["SHOP_WW"]); i = info(code); seen.add(code)
        area = i.get("area") or str(r["AREA"]).strip()
        shops.append({"code": code, "shop": str(r["SHOP_NAME"]).strip(), "area": area,
                      "region": i.get("region") or (area_to_region or {}).get(area, str(r["ZONE"])),
                      "type": i.get("type") or str(r["SHOP_TYPE"]),
                      "target": int(r[tcol]), "actual": int(per_shop.get(code, 0))})
    extra = 0
    for code, q in per_shop.items():
        if code in seen: continue
        i = info(code); area = i.get("area") or ""
        shops.append({"code": int(code), "shop": i.get("shop") or str(code), "area": area,
                      "region": i.get("region") or (area_to_region or {}).get(area, ""),
                      "type": i.get("type") or "", "target": 0, "actual": int(q)})
        extra += int(q)
    if extra:
        print(f"    True Mobile Care: {extra} units in shops that are not in the target file (target 0)")

    thai, other = build_thai_name_map(tsm_df, contest_xlsx_path)
    f["SALE_CODE"] = f["SALE_CODE"].astype(str).str.strip()
    shop_by = {s["code"]: s for s in shops}

    # Individual target: sheet 'Individual Target', column S ('QTY' = per-person
    # target units; sums to the shop target). One row per (employee, shop).
    ind = {}
    if individual_xlsx_path and os.path.exists(individual_xlsx_path):
        d = pd.read_excel(individual_xlsx_path, sheet_name="Individual Target", header=1)
        qcol = d.columns[18]
        d = d[d["emp_id8"].notna() & pd.to_numeric(d["shop_code"], errors="coerce").notna()].copy()
        d["shop_code"] = pd.to_numeric(d["shop_code"]).astype(int)
        for _, r in d.iterrows():
            key = (str(r["emp_id8"]).strip(), int(r["shop_code"]))
            fn = (str(r["name_eng"]).strip() if pd.notna(r["name_eng"]) else "") + " " + (str(r["sname_eng"]).strip() if pd.notna(r["sname_eng"]) else "")
            e = ind.setdefault(key, {"target": 0.0, "name": fn.strip(), "emp": str(r["emp_type"]) if pd.notna(r["emp_type"]) else ""})
            e["target"] += float(r[qcol]) if pd.notna(r[qcol]) else 0.0

    actual_by = {(sc, int(code)): (int(g["QTY"].sum()), g["EMP_TYPE"].dropna().astype(str), str(g["SALE_NAME"].iloc[0]).strip())
                 for (sc, code), g in f.groupby(["SALE_CODE", "SHOP_CODE"])}
    sales = []
    for key in sorted(set(actual_by) | set(ind)):
        sc, code = key
        qty, emp, raw = actual_by.get(key, (0, None, ""))
        i = ind.get(key, {})
        name = thai.get(sc)
        if not name and i.get("name") and _THAI_RE.search(i["name"]):
            name = i["name"]
        if not name:
            name = other.get(sc) or raw or i.get("name") or sc
        empType = (emp.iloc[0] if emp is not None and len(emp) else "") or i.get("emp", "")
        s_ = shop_by.get(code)
        if s_ is None:
            inf = info(code)
            s_ = {"shop": inf.get("shop", str(code)), "area": inf.get("area", ""), "region": inf.get("region", ""), "type": inf.get("type", "")}
        sales.append({"saleId": sc, "name": name, "empType": empType, "code": code, "shop": s_.get("shop", ""),
                      "area": s_.get("area", ""), "region": s_.get("region", ""), "type": s_.get("type", ""),
                      "qty": qty, "target": round(i.get("target", 0.0), 4)})
    n_people = len({x["saleId"] for x in sales})
    en_codes = len({x["saleId"] for x in sales if not _THAI_RE.search(x["name"])})
    print(f"    True Mobile Care: {sum(per_shop.values()):,} / {sum(x['target'] for x in shops):,} units | "
          f"{n_people} salespeople ({sum(1 for x in sales if x['target']>0)} with an individual target, "
          f"indiv. target total {sum(x['target'] for x in sales):,.0f}; {en_codes} without a Thai name on file)")
    return {"shops": shops, "daily": daily, "sales": sales, "meta": {"asOf": last_day.strftime("%Y-%m-%d")}}

_PREV_CACHE = {}
def _read_prev_raw(path):
    """Prior-month TSM (columns needed by the Trade In / Extended W. tabs), read once."""
    if path in _PREV_CACHE:
        return _PREV_CACHE[path]
    cols = ["DATE", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "AREA", "REGION", "CUSTOM_PRODGROUP", "CUSTOM_BRAND",
            "QTY", "Trade In", "Price Tier Device", "EMP_TYPE", "NET_AMOUNT", "DISCOUNT_AMOUNT", "PRICE", "Extended", "Price Extended"]
    df = pd.read_excel(path, sheet_name="TSM", usecols=lambda c: c in cols)
    _PREV_CACHE[path] = df
    return df

def export_trade_in(tsm_df, shop_lookup, area_to_region=None, contest_xlsx_path=None, prev_xlsx_path=None):
    """Trade In tab. Trade-in units = TSM column 'Trade In' (col AT, flag per order
    line) restricted to CUSTOM_PRODGROUP == HANDSET; rate = trade-in units / Handset
    units. Returns a compact cube (dimension tables + integer-coded rows) so the page
    can re-aggregate under any filter, plus last month's cube (same shape, fewer
    dims) from the prior-month TSM file for a same-days comparison."""
    TIERS = ["0-10,0000", "10,000-20,000", "20,000-35,000", "35,000-50,000", "50,000 ขึ้นไป"]
    def prep(df):
        d = df[df["CUSTOM_PRODGROUP"].astype(str).str.upper() == "HANDSET"].copy()
        d["SHOP_CODE"] = pd.to_numeric(d["SHOP_CODE"], errors="coerce")
        d = d.dropna(subset=["SHOP_CODE"]); d["SHOP_CODE"] = d["SHOP_CODE"].astype(int)
        d["DATE"] = pd.to_datetime(d["DATE"])
        d["QTY"] = pd.to_numeric(d["QTY"], errors="coerce").fillna(0)
        d["TR"] = (pd.to_numeric(d["Trade In"], errors="coerce").fillna(0) > 0) * d["QTY"]
        d["Price Tier Device"] = d["Price Tier Device"].fillna("").astype(str).str.strip()
        d["CUSTOM_BRAND"] = d["CUSTOM_BRAND"].fillna("OTHER").astype(str).str.strip()
        d["EMP_TYPE"] = d["EMP_TYPE"].fillna("(ไม่ระบุ)").astype(str).str.strip()
        for c in ("NET_AMOUNT", "DISCOUNT_AMOUNT", "PRICE"):
            d[c] = pd.to_numeric(d[c], errors="coerce").fillna(0)
        d["GROSS"] = d["PRICE"] * d["QTY"]
        return d
    cur = prep(tsm_df)
    last = cur["DATE"].max().normalize()
    cur = cur[(cur["DATE"].dt.year == last.year) & (cur["DATE"].dt.month == last.month)]
    prev = None
    if prev_xlsx_path and os.path.exists(prev_xlsx_path):
        try:
            pdf = _read_prev_raw(prev_xlsx_path)
            prev = prep(pdf)
            pm = (last.replace(day=1) - pd.Timedelta(days=1))
            prev = prev[(prev["DATE"].dt.year == pm.year) & (prev["DATE"].dt.month == pm.month)]
            prev_label = pm.strftime("%b %Y")
        except Exception as e:
            print("    Trade In: prior-month file unreadable:", e); prev = None
    if prev is None or prev.empty:
        prev = None; prev_label = ""

    shops, shop_ix = [], {}
    def shop_i(code, row=None):
        if code in shop_ix: return shop_ix[code]
        i = shop_lookup.get(str(code), {})
        area = i.get("area") or (str(row["AREA"]) if row is not None else "")
        shops.append({"code": code, "shop": i.get("shop") or (str(row["SHOP NAME"]).strip() if row is not None else str(code)),
                      "area": area, "region": i.get("region") or (area_to_region or {}).get(area, "") or (str(row["REGION"]) if row is not None else ""),
                      "type": i.get("type") or (str(row["TYPE SHOP"]) if row is not None else "")})
        shop_ix[code] = len(shops) - 1; return shop_ix[code]
    firsts = cur.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")
    for code in sorted(cur["SHOP_CODE"].unique()): shop_i(int(code), firsts.loc[code])
    if prev is not None:
        pf = prev.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")
        for code in sorted(prev["SHOP_CODE"].unique()): shop_i(int(code), pf.loc[code])

    thai, other = build_thai_name_map(tsm_df, contest_xlsx_path)
    cur = cur.copy(); cur["SALE_CODE"] = cur["SALE_CODE"].astype(str).str.strip()
    sales, sale_ix = [], {}
    emp_mode = cur.groupby("SALE_CODE")["EMP_TYPE"].agg(lambda s: s.value_counts().index[0]).to_dict()
    nm_raw = cur.groupby("SALE_CODE")["SALE_NAME"].agg(lambda s: str(s.dropna().iloc[0]).strip() if s.notna().any() else "").to_dict()
    for sc in sorted(cur["SALE_CODE"].unique()):
        sale_ix[sc] = len(sales)
        sales.append({"id": sc, "name": thai.get(sc) or other.get(sc) or nm_raw.get(sc) or sc, "emp": emp_mode.get(sc, "")})

    brands = sorted(set(cur["CUSTOM_BRAND"]) | (set(prev["CUSTOM_BRAND"]) if prev is not None else set()))
    brand_ix = {b: i for i, b in enumerate(brands)}
    emps = sorted(set(cur["EMP_TYPE"]) | (set(prev["EMP_TYPE"]) if prev is not None else set()))
    emp_ix = {e: i for i, e in enumerate(emps)}
    tiers = TIERS + sorted(t for t in (set(cur["Price Tier Device"]) | (set(prev["Price Tier Device"]) if prev is not None else set())) if t not in TIERS)
    tier_ix = {t: i for i, t in enumerate(tiers)}
    mm = cur.groupby("CUSTOM_MODEL").agg(brand=("CUSTOM_BRAND", "first"), cat=("CUSTOM_CATEGORY", "first"))
    models = []; model_ix = {}
    for m, r in mm.iterrows():
        model_ix[m] = len(models); models.append({"m": str(m), "b": brand_ix[r["brand"]], "c": str(r["cat"])})

    cur["_d"] = cur["DATE"].dt.day
    cur["_s"] = cur["SHOP_CODE"].map(shop_ix); cur["_sa"] = cur["SALE_CODE"].map(sale_ix)
    cur["_m"] = cur["CUSTOM_MODEL"].map(model_ix); cur["_t"] = cur["Price Tier Device"].map(tier_ix)
    t_ = cur["TR"] > 0
    cur["_tn"] = cur["NET_AMOUNT"].where(t_, 0); cur["_td"] = cur["DISCOUNT_AMOUNT"].where(t_, 0); cur["_tg"] = cur["GROSS"].where(t_, 0)
    g = cur.groupby(["_d", "_s", "_sa", "_m", "_t"], as_index=False)[["QTY", "TR", "NET_AMOUNT", "DISCOUNT_AMOUNT", "GROSS", "_tn", "_td", "_tg"]].sum()
    rows = g[["_d", "_s", "_sa", "_m", "_t", "QTY", "TR", "NET_AMOUNT", "DISCOUNT_AMOUNT", "GROSS", "_tn", "_td", "_tg"]].round(0).astype(int).values.tolist()

    prev_rows = []
    if prev is not None:
        pv = prev.copy(); pv["_d"] = pv["DATE"].dt.day
        pv["_s"] = pv["SHOP_CODE"].map(shop_ix); pv["_b"] = pv["CUSTOM_BRAND"].map(brand_ix)
        pv["_t"] = pv["Price Tier Device"].map(tier_ix); pv["_e"] = pv["EMP_TYPE"].map(emp_ix)
        gp = pv.groupby(["_d", "_s", "_b", "_t", "_e"], as_index=False)[["QTY", "TR"]].sum()
        prev_rows = gp[["_d", "_s", "_b", "_t", "_e", "QTY", "TR"]].round(0).astype(int).values.tolist()

    wk = cur.groupby("_d")["Flag Week"].agg(lambda s: str(s.value_counts().index[0]) if s.notna().any() else "").to_dict()
    days = [{"d": int(d), "date": pd.Timestamp(year=last.year, month=last.month, day=int(d)).strftime("%Y-%m-%d"),
             "dow": int(pd.Timestamp(year=last.year, month=last.month, day=int(d)).dayofweek), "wk": wk.get(int(d), "")}
            for d in range(1, last.day + 1)]
    tq, hq = int(cur["TR"].sum()), int(cur["QTY"].sum())
    print(f"    Trade In: {tq:,} / {hq:,} handset units ({tq/hq*100:.2f}%) | {len(rows):,} cube rows | " +
          (f"prior month {prev_label}: {int(prev['TR'].sum()):,} / {int(prev['QTY'].sum()):,}" if prev is not None else "no prior-month data"))
    return {"shops": shops, "sales": sales, "models": models, "brands": brands, "tiers": tiers, "emps": emps,
            "rows": rows, "prev": prev_rows, "days": days,
            "meta": {"asOf": last.strftime("%Y-%m-%d"), "month": last.strftime("%B %Y"), "daysInMonth": int(last.days_in_month), "prevLabel": prev_label}}

def export_extended_warranty(tsm_df, shop_lookup, area_to_region=None, contest_xlsx_path=None, prev_xlsx_path=None, target_xlsx_path=None):
    """Extended W. tab. Actual value = TSM 'Price Extended' (col AQ), actual units = 'Extended'
    (col AP, 1 per plan sold), both restricted to CUSTOM_PRODGROUP == HANDSET.
      * Value achievement = Price Extended / Target NET_AMOUNT (sheet 'Target by Store';
        per-person targets from sheet 'Individual Target' col S QTY / col T NET_AMOUNT).
      * Attach rate = Extended units / Handset units.
    Returns an integer-coded cube (like Trade In) + target tables + last month's cube."""
    TIERS = ["0-10,0000", "10,000-20,000", "20,000-35,000", "35,000-50,000", "50,000 ขึ้นไป"]
    def prep(df):
        d = df[df["CUSTOM_PRODGROUP"].astype(str).str.upper() == "HANDSET"].copy()
        d["SHOP_CODE"] = pd.to_numeric(d["SHOP_CODE"], errors="coerce")
        d = d.dropna(subset=["SHOP_CODE"]); d["SHOP_CODE"] = d["SHOP_CODE"].astype(int)
        d["DATE"] = pd.to_datetime(d["DATE"])
        d["QTY"] = pd.to_numeric(d["QTY"], errors="coerce").fillna(0)
        d["EQ"] = pd.to_numeric(d["Extended"], errors="coerce").fillna(0)
        d["EP"] = pd.to_numeric(d["Price Extended"], errors="coerce").fillna(0)
        d["Price Tier Device"] = d["Price Tier Device"].fillna("").astype(str).str.strip()
        d["CUSTOM_BRAND"] = d["CUSTOM_BRAND"].fillna("OTHER").astype(str).str.strip()
        d["EMP_TYPE"] = d["EMP_TYPE"].fillna("(ไม่ระบุ)").astype(str).str.strip()
        return d
    cur = prep(tsm_df)
    last = cur["DATE"].max().normalize()
    cur = cur[(cur["DATE"].dt.year == last.year) & (cur["DATE"].dt.month == last.month)].copy()
    prev, prev_label = None, ""
    if prev_xlsx_path and os.path.exists(prev_xlsx_path):
        try:
            prev = prep(_read_prev_raw(prev_xlsx_path))
            pm = (last.replace(day=1) - pd.Timedelta(days=1))
            prev = prev[(prev["DATE"].dt.year == pm.year) & (prev["DATE"].dt.month == pm.month)]
            prev_label = pm.strftime("%b %Y")
        except Exception as e:
            print("    Extended W.: prior-month file unreadable:", e); prev = None
    if prev is not None and prev.empty:
        prev = None; prev_label = ""

    # ---- targets ----
    st = None; ind = None
    if target_xlsx_path and os.path.exists(target_xlsx_path):
        st = pd.read_excel(target_xlsx_path, sheet_name="Target by Store")
        st = st[pd.to_numeric(st["SHOP_WW"], errors="coerce").notna()].copy()
        st["SHOP_WW"] = pd.to_numeric(st["SHOP_WW"]).astype(int)
        ind = pd.read_excel(target_xlsx_path, sheet_name="Individual Target", header=1)
        qcol, ncol = ind.columns[18], ind.columns[19]
        ind = ind[ind["emp_id8"].notna() & pd.to_numeric(ind["shop_code"], errors="coerce").notna()].copy()
        ind["shop_code"] = pd.to_numeric(ind["shop_code"]).astype(int)
        ind["_q"] = pd.to_numeric(ind[qcol], errors="coerce").fillna(0)
        ind["_n"] = pd.to_numeric(ind[ncol], errors="coerce").fillna(0)
    tgt_by_shop = {}
    if st is not None:
        for _, r in st.iterrows():
            tgt_by_shop[int(r["SHOP_WW"])] = (float(r["QTY"]), float(r["NET_AMOUNT"]), r)

    shops, shop_ix = [], {}
    def shop_i(code, row=None, trow=None):
        if code in shop_ix: return shop_ix[code]
        i = shop_lookup.get(str(code), {})
        area = i.get("area") or (str(row["AREA"]) if row is not None else (str(trow["AREA"]) if trow is not None else ""))
        nm = i.get("shop") or (str(row["SHOP NAME"]).strip() if row is not None else (str(trow["SHOP_NAME"]).strip() if trow is not None else str(code)))
        tq, tn, _ = tgt_by_shop.get(code, (0.0, 0.0, None))
        shops.append({"code": code, "shop": nm, "area": area,
                      "region": i.get("region") or (area_to_region or {}).get(area, "") or (str(row["REGION"]) if row is not None else ""),
                      "type": i.get("type") or (str(row["TYPE SHOP"]) if row is not None else (str(trow["SHOP_TYPE"]) if trow is not None else "")),
                      "tq": round(tq), "tn": round(tn)})
        shop_ix[code] = len(shops) - 1; return shop_ix[code]
    firsts = cur.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")
    for code in sorted(cur["SHOP_CODE"].unique()): shop_i(int(code), firsts.loc[code])
    if st is not None:
        for code, (_, _, trow) in sorted(tgt_by_shop.items()): shop_i(code, trow=trow)   # target shops with no handset sale yet
    if prev is not None:
        pf = prev.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")
        for code in sorted(prev["SHOP_CODE"].unique()): shop_i(int(code), pf.loc[code])

    # ---- people (Thai-only names) ----
    thai, other = build_thai_name_map(tsm_df, contest_xlsx_path)
    cur["SALE_CODE"] = cur["SALE_CODE"].astype(str).str.strip()
    sales, sale_ix = [], {}
    emp_mode = cur.groupby("SALE_CODE")["EMP_TYPE"].agg(lambda s_: s_.value_counts().index[0]).to_dict()
    nm_raw = cur.groupby("SALE_CODE")["SALE_NAME"].agg(lambda s_: str(s_.dropna().iloc[0]).strip() if s_.notna().any() else "").to_dict()
    ind_name = {}
    if ind is not None:
        for _, r in ind.iterrows():
            sc = str(r["emp_id8"]).strip()
            fn_ = ((str(r["name_eng"]).strip() if pd.notna(r["name_eng"]) else "") + " " + (str(r["sname_eng"]).strip() if pd.notna(r["sname_eng"]) else "")).strip()
            ind_name.setdefault(sc, (fn_, str(r["emp_type"]) if pd.notna(r["emp_type"]) else ""))
    def add_sale(sc):
        if sc in sale_ix: return sale_ix[sc]
        nm = thai.get(sc)
        fn_, em_ = ind_name.get(sc, ("", ""))
        if not nm and fn_ and _THAI_RE.search(fn_): nm = fn_
        if not nm: nm = other.get(sc) or nm_raw.get(sc) or fn_ or sc
        sale_ix[sc] = len(sales); sales.append({"id": sc, "name": nm, "emp": emp_mode.get(sc) or em_ or ""})
        return sale_ix[sc]
    for sc in sorted(cur["SALE_CODE"].unique()): add_sale(sc)

    brands = sorted(set(cur["CUSTOM_BRAND"]) | (set(prev["CUSTOM_BRAND"]) if prev is not None else set()))
    brand_ix = {b: i for i, b in enumerate(brands)}
    emps = sorted(set(cur["EMP_TYPE"]) | (set(prev["EMP_TYPE"]) if prev is not None else set()))
    emp_ix = {e: i for i, e in enumerate(emps)}
    tiers = TIERS + sorted(t for t in (set(cur["Price Tier Device"]) | (set(prev["Price Tier Device"]) if prev is not None else set())) if t not in TIERS)
    tier_ix = {t: i for i, t in enumerate(tiers)}
    mm = cur.groupby("CUSTOM_MODEL").agg(brand=("CUSTOM_BRAND", "first"), cat=("CUSTOM_CATEGORY", "first"))
    models = []; model_ix = {}
    for m, r in mm.iterrows():
        model_ix[m] = len(models); models.append({"m": str(m), "b": brand_ix[r["brand"]], "c": str(r["cat"])})
    plans = sorted({int(round(v)) for v in cur.loc[cur["EQ"] > 0, "EP"] if v > 0})
    plan_ix = {v: i for i, v in enumerate(plans)}

    cur["_d"] = cur["DATE"].dt.day
    cur["_s"] = cur["SHOP_CODE"].map(shop_ix); cur["_sa"] = cur["SALE_CODE"].map(sale_ix)
    cur["_m"] = cur["CUSTOM_MODEL"].map(model_ix); cur["_t"] = cur["Price Tier Device"].map(tier_ix)
    cur["_p"] = [plan_ix.get(int(round(v)), -1) if (e > 0 and v > 0) else -1 for v, e in zip(cur["EP"], cur["EQ"])]
    g = cur.groupby(["_d", "_s", "_sa", "_m", "_t", "_p"], as_index=False)[["QTY", "EQ", "EP"]].sum()
    rows = g[["_d", "_s", "_sa", "_m", "_t", "_p", "QTY", "EQ", "EP"]].round(0).astype(int).values.tolist()

    prev_rows = []
    if prev is not None:
        pv = prev.copy(); pv["_d"] = pv["DATE"].dt.day
        pv["_s"] = pv["SHOP_CODE"].map(shop_ix); pv["_b"] = pv["CUSTOM_BRAND"].map(brand_ix)
        pv["_t"] = pv["Price Tier Device"].map(tier_ix); pv["_e"] = pv["EMP_TYPE"].map(emp_ix)
        gp = pv.groupby(["_d", "_s", "_b", "_t", "_e"], as_index=False)[["QTY", "EQ", "EP"]].sum()
        prev_rows = gp[["_d", "_s", "_b", "_t", "_e", "QTY", "EQ", "EP"]].round(0).astype(int).values.tolist()

    # individual targets: [saleIx, shopIx, tQty, tNet]
    itarget = []
    if ind is not None:
        for (sc, code), gi in ind.assign(_sc=ind["emp_id8"].astype(str).str.strip()).groupby(["_sc", "shop_code"]):
            itarget.append([add_sale(sc), shop_i(int(code)), round(float(gi["_q"].sum()), 3), round(float(gi["_n"].sum()), 2)])

    days = [{"d": int(d), "date": pd.Timestamp(year=last.year, month=last.month, day=int(d)).strftime("%Y-%m-%d"),
             "dow": int(pd.Timestamp(year=last.year, month=last.month, day=int(d)).dayofweek)}
            for d in range(1, last.day + 1)]
    wk = {}
    if "Flag Week" in tsm_df.columns:
        w = tsm_df.assign(_d=pd.to_datetime(tsm_df["DATE"]).dt.day)
        wk = w.groupby("_d")["Flag Week"].agg(lambda s_: str(s_.value_counts().index[0]) if s_.notna().any() else "").to_dict()
    for d in days: d["wk"] = wk.get(d["d"], "")
    eq, ep, hq = int(cur["EQ"].sum()), int(cur["EP"].sum()), int(cur["QTY"].sum())
    tN = sum(x["tn"] for x in shops); tQ = sum(x["tq"] for x in shops)
    print(f"    Extended W.: {ep:,.0f} THB / target {tN:,.0f} ({ep/tN*100 if tN else 0:.1f}%) | {eq:,} units / target {tQ:,} | attach {eq/hq*100:.2f}% of {hq:,} handsets | "
          f"{len(rows):,} cube rows | " + (f"prior month {prev_label}: {int(prev['EQ'].sum()):,} units / {int(prev['EP'].sum()):,} THB" if prev is not None else "no prior-month data"))
    return {"shops": shops, "sales": sales, "models": models, "brands": brands, "tiers": tiers, "emps": emps, "plans": plans,
            "rows": rows, "prev": prev_rows, "itarget": itarget, "days": days,
            "meta": {"asOf": last.strftime("%Y-%m-%d"), "month": last.strftime("%B %Y"), "daysInMonth": int(last.days_in_month), "prevLabel": prev_label}}

# ---- SF+ Game Plan (config from the Samsung Incentive brief "SF+ Game Plan") ----
SFP_PLAN = {"models": ["GALAXY S26FE 5G", "GALAXY S25FE 5G", "GALAXY A57 5G", "GALAXY A37 5G"],
            "short": {"GALAXY S26FE 5G": "S26 FE", "GALAXY S25FE 5G": "S25 FE", "GALAXY A57 5G": "A57", "GALAXY A37 5G": "A37"},
            "start": "2026-10-09", "end": "2026-11-01", "baseline": 300,
            "tiers": [{"n": "Tier 1", "target": 550, "voucher": 100}, {"n": "Tier 2", "target": 620, "voucher": 200}, {"n": "Tier 3", "target": 660, "voucher": 300}]}

def export_sf_plus(tsm_df, shop_lookup, area_to_region=None, contest_xlsx_path=None):
    """SF+ Game Plan tab. Actual = TSM 'QTY SF+' (col AR) on CUSTOM_PRODGROUP == HANDSET rows of the four
    measured models (S26 FE / S25 FE / A57 / A37), Period 9 Oct - 1 Nov (24 days), WW target tiers
    360/400/450 units with a retroactive voucher of 100/200/300 THB per unit (all units from the 1st)."""
    P = SFP_PLAN
    d = tsm_df[tsm_df["CUSTOM_PRODGROUP"].astype(str).str.upper() == "HANDSET"].copy()
    d["DATE"] = pd.to_datetime(d["DATE"]).dt.normalize()
    d["QTY"] = pd.to_numeric(d["QTY"], errors="coerce").fillna(0)
    d["SF"] = pd.to_numeric(d["QTY SF+"], errors="coerce").fillna(0)
    d["SHOP_CODE"] = pd.to_numeric(d["SHOP_CODE"], errors="coerce")
    d = d.dropna(subset=["SHOP_CODE"]); d["SHOP_CODE"] = d["SHOP_CODE"].astype(int)
    start, end = pd.Timestamp(P["start"]), pd.Timestamp(P["end"])
    last = min(d["DATE"].max().normalize(), end)
    d = d[(d["DATE"] >= start) & (d["DATE"] <= end)]
    excl = d[(d["SF"] > 0) & ~d["CUSTOM_MODEL"].isin(P["models"])]
    cur = d[d["CUSTOM_MODEL"].isin(P["models"])].copy()
    cur["SALE_CODE"] = cur["SALE_CODE"].astype(str).str.strip()
    cur["EMP_TYPE"] = cur["EMP_TYPE"].fillna("(ไม่ระบุ)").astype(str).str.strip()
    shops, shop_ix = [], {}
    firsts = cur.drop_duplicates("SHOP_CODE").set_index("SHOP_CODE")
    for code in sorted(cur["SHOP_CODE"].unique()):
        r = firsts.loc[code]; i = shop_lookup.get(str(code), {}); area = i.get("area") or str(r["AREA"])
        shop_ix[int(code)] = len(shops)
        shops.append({"code": int(code), "shop": i.get("shop") or str(r["SHOP NAME"]).strip(), "area": area,
                      "region": i.get("region") or (area_to_region or {}).get(area, "") or str(r["REGION"]),
                      "type": i.get("type") or str(r["TYPE SHOP"])})
    thai, other = build_thai_name_map(tsm_df, contest_xlsx_path)
    emp_mode = cur.groupby("SALE_CODE")["EMP_TYPE"].agg(lambda s_: s_.value_counts().index[0]).to_dict()
    nm_raw = cur.groupby("SALE_CODE")["SALE_NAME"].agg(lambda s_: str(s_.dropna().iloc[0]).strip() if s_.notna().any() else "").to_dict()
    sales, sale_ix = [], {}
    for sc in sorted(cur["SALE_CODE"].unique()):
        sale_ix[sc] = len(sales); sales.append({"id": sc, "name": thai.get(sc) or other.get(sc) or nm_raw.get(sc) or sc, "emp": emp_mode.get(sc, "")})
    models = [P["short"][m] for m in P["models"]]; model_ix = {m: i for i, m in enumerate(P["models"])}
    subs = sorted(cur["CUSTOM_SUBMODEL"].fillna("").astype(str).str.strip().unique()); sub_ix = {s: i for i, s in enumerate(subs)}
    days_all = pd.date_range(start, last)
    day_ix = {t: i for i, t in enumerate(days_all)}
    cur["_d"] = cur["DATE"].map(day_ix); cur["_s"] = cur["SHOP_CODE"].map(shop_ix); cur["_sa"] = cur["SALE_CODE"].map(sale_ix)
    cur["_m"] = cur["CUSTOM_MODEL"].map(model_ix); cur["_u"] = cur["CUSTOM_SUBMODEL"].fillna("").astype(str).str.strip().map(sub_ix)
    g = cur.groupby(["_d", "_s", "_sa", "_m", "_u"], as_index=False)[["SF", "QTY"]].sum()
    rows = g[["_d", "_s", "_sa", "_m", "_u", "SF", "QTY"]].round(0).astype(int).values.tolist()
    wk = {}
    if "Flag Week" in tsm_df.columns:
        w = tsm_df.assign(_dt=pd.to_datetime(tsm_df["DATE"]).dt.normalize())
        wk = w.groupby("_dt")["Flag Week"].agg(lambda s_: str(s_.value_counts().index[0]) if s_.notna().any() else "").to_dict()
    days = [{"date": t.strftime("%Y-%m-%d"), "dow": int(t.dayofweek), "wk": wk.get(t, "")} for t in pd.date_range(start, end)]
    other_sf = [[str(k), int(v)] for k, v in excl.groupby("CUSTOM_MODEL")["SF"].sum().sort_values(ascending=False).items() if v > 0]
    sf, tot = int(cur["SF"].sum()), int(cur["QTY"].sum())
    print(f"    SF+ Game Plan: {sf:,} SF+ units on 4 models ({tot:,} handsets, {sf/tot*100 if tot else 0:.1f}%) | period {P['start']}..{P['end']} as of {last.date()} | "
          f"tiers {[t['target'] for t in P['tiers']]} | SF+ on other models: {sum(v for _, v in other_sf)}")
    return {"shops": shops, "sales": sales, "models": models, "subs": subs, "rows": rows, "days": days, "otherSf": other_sf,
            "plan": {"baseline": P["baseline"], "tiers": P["tiers"], "start": P["start"], "end": P["end"], "nDays": len(days)},
            "meta": {"asOf": last.strftime("%Y-%m-%d"), "elapsed": len(days_all)}}

# ---- Retention tab (Daily_Retention_Mail workbook) ----
RET_PRODUCTS = ["True Mobile", "True Online", "True Visions", "Fix Line Plus"]
# metric order per product: req, save, cancel, revenue req, revenue save, churn (value), VCS req, VCS save, VCS cancel
RET_SHOP_COLS = [[8, 9, 10, 14, 15, 16, 26, 27, 28], [34, 35, 36, 40, 41, 42, 52, 53, 54], [60, 61, 62, 66, 67, 68, 78, 79, 80], [86, 87, 88, None, None, None, None, None, None]]
RET_STAFF_COLS = [[10, 11, 12, 16, 17, 18, None, None, None], [28, 29, 30, 34, 35, 36, None, None, None], [46, 47, 48, 52, 53, 54, None, None, None], [64, 65, 66, None, None, None, None, None, None]]

def export_retention(xlsx_path, tsm_df=None, contest_xlsx_path=None):
    """Retention tab. 'Data as of' = Summary!A1. Rows = sheets Shop_ไม่รวมVCS + DTAC_Shop (union by shop
    code; DTAC_Shop is a subset) and Staff, restricted to ShopType == 'WW'."""
    import openpyxl
    wb = openpyxl.load_workbook(xlsx_path, read_only=True, data_only=True)
    a1 = str(wb["Summary"]["A1"].value or "")
    wb.close()
    m = re.search(r"(\d{1,2})/(\d{1,2})/(\d{4})", a1)
    as_of = f"{m.group(3)}-{int(m.group(2)):02d}-{int(m.group(1)):02d}" if m else ""
    def num(x):
        v = pd.to_numeric(x, errors="coerce")
        return 0 if pd.isna(v) else int(round(float(v)))
    def read(sheet):
        d = pd.read_excel(xlsx_path, sheet_name=sheet, header=3)
        d = d[pd.to_numeric(d["Shopcode"], errors="coerce").notna()].copy()
        d["Shopcode"] = pd.to_numeric(d["Shopcode"]).astype(int)
        return d[d["ShopType"].astype(str).str.strip() == "WW"]
    s1, s2 = read("Shop_ไม่รวมVCS"), read("DTAC_Shop")
    shop_df = pd.concat([s1, s2[~s2["Shopcode"].isin(s1["Shopcode"])]], ignore_index=True)
    staff_df = read("Staff")
    def vals(r, cols):
        out = []
        for pc in cols:
            for c in pc:
                out.append(0 if c is None else num(r.iloc[c]))
        return out
    shops = []
    for _, r in shop_df.iterrows():
        shops.append({"code": int(r["Shopcode"]), "name": str(r["ShopName"]).strip(), "region": str(r["Region"]).strip(),
                      "area": str(r["Area WW"]).strip() if pd.notna(r["Area WW"]) else "(ไม่ระบุ)",
                      "kpi": str(r["KPIType"]).strip() if pd.notna(r["KPIType"]) else "(ไม่ระบุ)", "v": vals(r, RET_SHOP_COLS)})
    shop_ix = {s["code"]: i for i, s in enumerate(shops)}
    thai, other = ({}, {})
    if tsm_df is not None:
        try: thai, other = build_thai_name_map(tsm_df, contest_xlsx_path)
        except Exception as e: print("    Retention: Thai-name map unavailable:", e)
    staff, dropped = [], 0
    for _, r in staff_df.iterrows():
        if r["Shopcode"] not in shop_ix: dropped += 1; continue
        eid = str(r["EmpID"]).strip()
        nm = thai.get(eid) or other.get(eid) or (str(r["EmpName"]).strip() if pd.notna(r["EmpName"]) else eid)
        staff.append({"id": eid, "name": nm, "pos": str(r["Position"]).strip() if pd.notna(r["Position"]) else "(ไม่ระบุ)",
                      "shop": shop_ix[r["Shopcode"]], "v": vals(r, RET_STAFF_COLS)})
    t = [sum(s["v"][p * 9 + k] for s in shops) for p in range(1) for k in range(3)]
    ts = [sum(s["v"][k] for s in staff) for k in range(3)]
    print(f"    Retention: as of {as_of} | {len(shops)} WW shops, {len(staff)} staff rows ({len({s['id'] for s in staff})} people; {dropped} dropped) | "
          f"True Mobile shop-level req/save/cancel {t[0]:,}/{t[1]:,}/{t[2]:,} | staff-level {ts[0]:,}/{ts[1]:,}/{ts[2]:,}")
    return {"asOf": as_of, "products": RET_PRODUCTS, "shops": shops, "staff": staff, "source": a1.strip()}

def export_sheep(sheep_xlsx_path, area_to_region=None):
    """Reads Sheep_Report.xlsx ("Export" sheet) and normalises it to the
    same record shape used by Handset/Accessories. Returns ([], None) if
    the file can't be found/read, so the dashboard still builds (Sheep
    page just shows 0s) instead of hard-failing.

    Some Sheep report exports omit the "Regional" column -- when that
    happens, `area_to_region` (built from the TSM sheet's AREA->REGION
    mapping) is used to derive it from AREA instead."""
    if not sheep_xlsx_path or not os.path.exists(sheep_xlsx_path):
        return [], None
    df = pd.read_excel(sheep_xlsx_path, sheet_name="Export")
    df = df.dropna(subset=["SHOP_CODE"]).copy()
    if "ORDER_DATE" not in df.columns:
        raise ValueError(
            f"'{sheep_xlsx_path}' is missing an ORDER_DATE column -- this doesn't look like a "
            "valid Sheep Report export (got columns: " + ", ".join(df.columns) + "). "
            "Please re-export and try again."
        )
    df["ORDER_DATE"] = pd.to_datetime(df["ORDER_DATE"], errors="coerce")
    df = df.dropna(subset=["ORDER_DATE"])
    df["SHOP_TYPE"] = df["SHOP_TYPE"].astype(str).str.replace("True Shop ", "", regex=False).str.strip()
    if "Regional" not in df.columns:
        if area_to_region is None:
            raise ValueError(
                f"'{sheep_xlsx_path}' has no Regional column and no TSM Area->Region "
                "mapping was supplied to derive it from."
            )
        df["Regional"] = df["AREA"].map(area_to_region)
    df = df.sort_values(["ORDER_DATE", "Regional", "AREA", "SHOP_NAME"])
    records = [
        {
            "date": r["ORDER_DATE"].strftime("%Y-%m-%d"),
            "region": r["Regional"],
            "area": r["AREA"],
            "code": str(int(r["SHOP_CODE"])),
            "shop": str(r["SHOP_NAME"]).strip(),
            "type": r["SHOP_TYPE"],
            "qty": int(r["QTY"]),
            "rev": round(float(r["NET_AMOUNT"]), 2),
            "brand": r["BRAND"],
            "model": r["ITEM_DESCRIPTION"],
        }
        for _, r in df.iterrows()
    ]
    return records, df

def load_retention_roster(roster_xlsx_path, shop_lookup):
    """Reads the authoritative Retention Champion staff list
    (List_Staff_Retention.xlsx, 'Sheet1') and returns a roster list in
    the same shape as export_emp_type's roster. `shop_lookup` maps
    SHOP_CODE (str) -> {shop, type, region, area} from the TSM sheet, so
    employees are located even though this file only has shop_code.
    Some employees appear twice (e.g. an extra "Central Bangna" row) --
    the FIRST occurrence (their primary shop) is kept.
    """
    if not roster_xlsx_path or not os.path.exists(roster_xlsx_path):
        return None
    df = pd.read_excel(roster_xlsx_path, sheet_name="Sheet1")
    df = df.drop_duplicates(subset=["emp_id8"], keep="first")
    roster = []
    for _, r in df.iterrows():
        code = str(r["shop_code"])
        shop_info = shop_lookup.get(code, {})
        roster.append({
            "code": str(r["emp_id8"]),
            "name": (str(r["name_eng"]).strip() + " " + str(r["sname_eng"]).strip()).strip(),
            "shopCode": code,
            "shop": shop_info.get("shop", str(r["Shop Name"]).strip()),
            "type": shop_info.get("type"),
            "region": shop_info.get("region"),
            "area": shop_info.get("area"),
        })
    return roster

def export_emp_type(df, emp_type, external_roster=None):
    """Reads all TSM rows for a given EMP_TYPE and returns:
    - records: the HANDSET rows for that employee group (used to track
      Entry Model sales per individual salesperson)
    - roster: every distinct (SALE_CODE, SALE_NAME) for that EMP_TYPE.
      If `external_roster` (from load_retention_roster) is given, it is
      used as the AUTHORITATIVE staff list -- so every staff member
      shows up, including those with zero sales of anything so far --
      and is merged with anyone found only in the TSM data (e.g. a very
      recent transfer not yet on the official list).
    """
    sub = df[df["EMP_TYPE"] == emp_type].copy()

    if external_roster is not None:
        roster_by_code = {e["code"]: e for e in external_roster}
        tsm_roster_df = sub[["SALE_CODE", "SALE_NAME", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "REGION", "AREA"]].drop_duplicates(subset=["SALE_CODE"])
        for _, r in tsm_roster_df.iterrows():
            code = str(r["SALE_CODE"])
            if code not in roster_by_code:
                roster_by_code[code] = {
                    "code": code,
                    "name": str(r["SALE_NAME"]).strip(),
                    "shopCode": _sc(r["SHOP_CODE"]),
                    "shop": str(r["SHOP NAME"]).strip(),
                    "type": r["TYPE SHOP"],
                    "region": r["REGION"],
                    "area": r["AREA"],
                }
        roster = list(roster_by_code.values())
    else:
        roster_df = sub[["SALE_CODE", "SALE_NAME", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "REGION", "AREA"]].drop_duplicates(subset=["SALE_CODE"])
        roster = [
            {
                "code": str(r["SALE_CODE"]),
                "name": str(r["SALE_NAME"]).strip(),
                "shopCode": _sc(r["SHOP_CODE"]),
                "shop": str(r["SHOP NAME"]).strip(),
                "type": r["TYPE SHOP"],
                "region": r["REGION"],
                "area": r["AREA"],
            }
            for _, r in roster_df.iterrows()
        ]

    h = sub[sub["CUSTOM_PRODGROUP"] == "HANDSET"].copy()
    h = h[["DATE", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "REGION", "AREA", "SALE_CODE", "SALE_NAME", "QTY", "CUSTOM_BRAND", "CUSTOM_MODEL"]]
    h["DATE"] = pd.to_datetime(h["DATE"])
    h = h.sort_values(["DATE", "SALE_NAME"])
    records = [
        {
            "date": r["DATE"].strftime("%Y-%m-%d"),
            "code": _sc(r["SHOP_CODE"]),
            "shop": str(r["SHOP NAME"]).strip(),
            "type": r["TYPE SHOP"],
            "region": r["REGION"],
            "area": r["AREA"],
            "empCode": str(r["SALE_CODE"]),
            "empName": str(r["SALE_NAME"]).strip(),
            "qty": int(r["QTY"]),
            "brand": r["CUSTOM_BRAND"],
            "model": r["CUSTOM_MODEL"],
        }
        for _, r in h.iterrows()
    ]
    return records, roster

def export_mongkol(contest_xlsx_path, area_to_region=None):
    """Reads the 'เบอร์มงคล' sales contest roster (sheet
    'รายชื่อผู้เข้าร่วมการแข่งขัน', header on row 4) and returns
    (records, data_as_of). Returns ([], None) if the file isn't found, so
    the dashboard still builds -- the contest tab just shows 0 rows."""
    if not contest_xlsx_path or not os.path.exists(contest_xlsx_path):
        return [], None
    raw = pd.read_excel(contest_xlsx_path, sheet_name="รายชื่อผู้เข้าร่วมการแข่งขัน", header=None, nrows=2)
    data_as_of_cell = raw.iloc[0, 9]
    data_as_of = pd.to_datetime(data_as_of_cell).strftime("%Y-%m-%d") if pd.notna(data_as_of_cell) else None
    # The header cell is sometimes left on the previous month-end; only
    # show it as "Data as of" when it falls inside the contest month.
    if data_as_of and not data_as_of.startswith("2026-10"):
        data_as_of = None

    df = pd.read_excel(contest_xlsx_path, sheet_name="รายชื่อผู้เข้าร่วมการแข่งขัน", header=3)
    df.columns = [str(c).strip() for c in df.columns]
    # Current contest month: the October roster carries "Actual Oct 69"
    # (the previous month's END MTH column is kept in the file only as
    # history and is deliberately ignored -- no baseline comparison).
    oct_col = next(c for c in df.columns if c.startswith("Actual Oct"))
    df = df[df["Sales ID"].notna()]
    # Anyone can join the contest; a few people appear on two shop rows
    # with the same personal total -- count each Sales ID once.
    df = df.sort_values(oct_col, ascending=False, kind="stable").drop_duplicates("Sales ID", keep="first")

    def region_of(area):
        if area_to_region and area in area_to_region:
            return area_to_region[area]
        return None

    records = []
    for _, r in df.iterrows():
        area = r["Area"]
        records.append({
            "saleId": str(r["Sales ID"]),
            "name": str(r["Sale Name"]).strip(),
            "empType": r["emp_type"],
            "shopCode": str(r["shop_code"]),
            "shop": str(r["Shop Name"]).strip(),
            "area": area,
            "type": r["Shop Type"],
            "region": region_of(area),
            "octActual": int(r[oct_col]) if pd.notna(r[oct_col]) else 0,
        })
    return records, data_as_of

def export_sale_score_html(html_path):
    """Reads the standalone Sale Score Leaderboard dashboard (a
    self-contained HTML file with its own CSS/JS/embedded data) and
    returns its raw text, or None if not found. It's embedded into the
    main dashboard as an isolated iframe (via a Blob URL at runtime)
    rather than merged into the shared page, so its CSS variables and
    JS globals can never collide with the rest of the dashboard."""
    if not html_path or not os.path.exists(html_path):
        return None
    with open(html_path, "r", encoding="utf-8") as fh:
        return fh.read()

def export_sale_performance(xlsx_path):
    """Sale Performance tab: the Sale Score Power BI export (one row per product x shop), shown as a table.
    Total row of the file is kept for the unfiltered footer; filtered footers are recomputed in the page."""
    import re
    raw = pd.read_excel(xlsx_path)
    cols = ["PRODUCT","SHOP_CODE","SHOP_NAME","Regional","AREA","CHANNEL","DATA_ASOF_DATE - Day","TG_Net Amount","NET_AMOUNT","RR_Net Amount","%Ach Net Amount","MOM Net Amount","TG_QTY","QTY","RR_QTY","%Ach QTY","MOM QTY"]
    tot = raw[raw["PRODUCT"].astype(str).str.strip().str.lower() == "total"]
    total = [None if pd.isna(tot.iloc[0][c]) else float(tot.iloc[0][c]) for c in cols[7:]] if len(tot) else None
    year = month = ""
    for v in raw["PRODUCT"].dropna().astype(str):
        if v.startswith("Applied filters"):
            m1 = re.search(r"Year is (\d{4})", v); m2 = re.search(r"MonthYearID is (\d{6})", v)
            year = m1.group(1) if m1 else ""; month = m2.group(1) if m2 else ""
    d = raw[raw["SHOP_CODE"].notna()].copy()
    rows = []
    for r in d.itertuples(index=False):
        rec = dict(zip(raw.columns, r))
        def f(c, nd):
            v = rec[c]; return None if pd.isna(v) else round(float(v), nd)
        rows.append([str(rec["PRODUCT"]).strip(), str(int(rec["SHOP_CODE"])), str(rec["SHOP_NAME"]).strip(), str(rec["Regional"]).strip(), str(rec["AREA"]).strip(), str(rec["CHANNEL"]).strip(),
                     int(rec["DATA_ASOF_DATE - Day"]) if not pd.isna(rec["DATA_ASOF_DATE - Day"]) else None,
                     f("TG_Net Amount",0), f("NET_AMOUNT",0), f("RR_Net Amount",0), f("%Ach Net Amount",4), f("MOM Net Amount",4),
                     f("TG_QTY",1), f("QTY",0), f("RR_QTY",1), f("%Ach QTY",4), f("MOM QTY",4)])
    return {"rows": rows, "total": total, "year": year, "month": month,
            "day": max([r[6] for r in rows if r[6] is not None] or [0]), "source": os.path.basename(xlsx_path)}


# ---------------------------------------------------------------------------
# Service Level tab (Daily AWT -- average waiting time / service level)
# ---------------------------------------------------------------------------
SL_GROUPS = ["Overall", "AFS", "Retention", "Payment", "BC AFS", "BC Payment"]
# 0-based column of each group's "Total" block in sheet TempAWT (TT Q, Trans.In Target, WT, SL%)
SL_GROUP_COLS = [9, 650, 778, 137, 521, 393]
# Targets (from the 'Matching' sheet header + 'Data Source' sheet). None = no SL% target defined in the file.
SL_TARGET_SL = [0.795, 0.795, None, None, 0.846, None]
SL_TARGET_WT_MIN = [10, 10, 10, 10, 5, 5]
SL_HISTORY_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "service_level_history.json")


def _sl_num(x):
    import datetime as _dt
    if isinstance(x, _dt.time):
        return x.hour * 3600 + x.minute * 60 + x.second + x.microsecond / 1e6
    try:
        return float(x)
    except (TypeError, ValueError):
        return 0.0


def _sl_wt_seconds(x):
    """WT cells are either a time-of-day value or (for some groups) an Excel day fraction."""
    import datetime as _dt
    if isinstance(x, _dt.time):
        return _sl_num(x)
    try:
        return float(x) * 86400.0
    except (TypeError, ValueError):
        return 0.0


def export_service_level(awt_path, shop_update_path):
    """Daily AWT workbook (sheet TempAWT, one day per file) + Data Shop update (shop master).
    Each day's shop rows are merged into service_level_history.json so the tab accumulates days.
    Returns the SL_DATA dict for the page (or an empty skeleton)."""
    import datetime as _dt
    import openpyxl
    hist = {"days": {}, "shops": {}}
    if os.path.exists(SL_HISTORY_FILE):
        try:
            hist = json.load(open(SL_HISTORY_FILE, encoding="utf-8"))
        except Exception:
            pass
    if awt_path and os.path.exists(awt_path):
        wb = openpyxl.load_workbook(awt_path, read_only=True, data_only=True)
        if "TempAWT" in wb.sheetnames:
            rows = list(wb["TempAWT"].iter_rows(values_only=True))
            d = rows[2][1] if len(rows) > 2 and len(rows[2]) > 1 else None
            if isinstance(d, _dt.datetime):
                day = d.strftime("%Y-%m-%d")
                start = next((i for i, r in enumerate(rows) if r and r[0] == "ShopCode"), None)
                recs = {}
                if start is not None:
                    for r in rows[start + 1:]:
                        if not r or not r[0]:
                            continue
                        code = str(r[0]).strip()
                        vals = []
                        for c in SL_GROUP_COLS:
                            q, inn, wt = _sl_num(r[c]), _sl_num(r[c + 1]), _sl_wt_seconds(r[c + 2])
                            vals += [int(q), int(inn), round(wt, 1)]
                        if any(vals[0::3]):
                            recs[code] = vals
                        hist["shops"][code] = {"name": (r[1] or "").strip() if isinstance(r[1], str) else str(r[1] or ""),
                                               "sector": r[4] or r[2] or "", "regionF": r[5] or "", "top": r[6] or ""}
                hist["days"][day] = recs
                json.dump(hist, open(SL_HISTORY_FILE, "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))
                print(f"    Service Level: day {day} | {len(recs)} shops with transactions | total Overall TT Q {sum(v[0] for v in recs.values()):,}")
            else:
                print("    WARNING Service Level: TempAWT!B3 has no date -- file ignored")
        else:
            print("    WARNING Service Level: sheet TempAWT not found -- file ignored")
    elif not hist["days"]:
        return {"groups": SL_GROUPS, "targetSl": SL_TARGET_SL, "targetWt": SL_TARGET_WT_MIN, "dates": [], "shops": [], "rows": []}

    master = {}
    if shop_update_path and os.path.exists(shop_update_path):
        su = pd.read_excel(shop_update_path, dtype=str)
        for _, r in su.iterrows():
            master[str(r["SHOP CODE"]).strip()] = {"name": r["SHOP NAME"], "type": r["TYPE SHOP"], "area": r["AREA"], "region": r["REGION"], "company": r.get("COMPANY", "WW")}
    dates = sorted(hist["days"])
    codes = sorted({c for d in dates for c in hist["days"][d]})
    shops, idx = [], {}
    for c in codes:
        m, h = master.get(c), hist["shops"].get(c, {})
        if m:
            shops.append({"code": c, "name": str(m["name"]).strip(), "type": m["type"], "area": m["area"], "region": m["region"], "ww": 1})
        else:
            shops.append({"code": c, "name": h.get("name", c), "type": h.get("top") or "Other", "area": h.get("sector") or "-", "region": h.get("regionF") or "-", "ww": 0})
        idx[c] = len(shops) - 1
    out_rows = []
    for di, d in enumerate(dates):
        for c, v in hist["days"][d].items():
            out_rows.append([di, idx[c]] + v)
    ww = sum(1 for s in shops if s["ww"])
    print(f"    Service Level: {len(dates)} day(s) {dates[0]}..{dates[-1]} | {len(shops)} shops ({ww} in Data Shop update WW, {len(shops)-ww} outside it) | master shops without AWT data: {len(set(master)-set(codes))}")
    return {"groups": SL_GROUPS, "targetSl": SL_TARGET_SL, "targetWt": SL_TARGET_WT_MIN, "dates": dates, "shops": shops, "rows": out_rows}


# ---------------------------------------------------------------------------
# TOL Regis & Connect tab (Data_TOL workbooks: current month = Nov, previous month = Oct for MoM)
# ---------------------------------------------------------------------------
TOL_STATUS = ["Connect", "Pending", "Cancel", "Un-Complete"]


def _tol_dates(s):
    """Date column may mix real dates and Excel serial numbers (Oct file) -- normalise both."""
    s2 = pd.to_numeric(s, errors="coerce")
    out = pd.to_datetime(s, errors="coerce")
    ser = s2.notna() & (s2 > 40000) & (s2 < 60000)
    return out.where(~ser, pd.to_datetime(s2.where(ser), unit="D", origin="1899-12-30"))


def export_tol(cur_path, prev_path=None):
    """Returns the TOL_DATA dict. ACTUAL rows only (TARGET rows give the per-shop TOL-CONNECT target).
    TOL-REGISTER rows carry SUBS_STATUS (Connect / Pending / Cancel / Un-Complete); TOL-CONNECT rows are activations."""
    empty = {"month": "", "prevMonth": "", "daysCur": 30, "daysPrev": 31, "asOf": "", "regions": [], "types": [], "shops": [],
             "pkgs": [], "handlers": [], "subs": [], "cur": {"reg": [], "con": []}, "prev": {"reg": [], "con": []}, "todo": [], "targets": {}}
    if not cur_path or not os.path.exists(cur_path):
        return empty
    cur_raw = pd.read_excel(cur_path)
    prev_raw = pd.read_excel(prev_path) if prev_path and os.path.exists(prev_path) else None
    last = _tol_dates(cur_raw["TM_KEY_DAY"]).max()
    month = last.strftime("%Y-%m")
    pmonth = (last.replace(day=1) - pd.Timedelta(days=1)).strftime("%Y-%m")

    def prep(d, mon):
        """Counting rules (same as the reference script): only KPI rows that have an APPOINT_DAY and a SUBS_STATUS,
        rows without a Region WW / Shop Name (0 or blank) are dropped, Lotus's is excluded.
        TOL-REGISTER is counted on REGISTER_DAY, TOL-CONNECT on APPOINT_DAY."""
        d = d[d["ACTUAL_TYPE"] == "ACTUAL"]
        d = d[d["APPOINT_DAY"].notna() & (d["FLAG_KPI"] == "KPI") & d["SUBS_STATUS"].notna()].copy()
        d = d[d["Region WW"].map(lambda v: isinstance(v, str)) & d["Shop Name"].map(lambda v: isinstance(v, str))]
        d = d[d["Shop Type"] != "Lotus's"].copy()
        d["_reg"] = _tol_dates(d["REGISTER_DAY"])
        d["_app"] = _tol_dates(d["APPOINT_DAY"])
        for c in ["Region WW", "Shop Name", "Shop Type"]:
            d[c] = d[c].astype(str).str.strip()
        d["PROMOTION_DESC"] = d["PROMOTION_DESC"].fillna("-").astype(str).str.strip()
        isreg = (d["SOURCES"] == "TOL-REGISTER") & (d["_reg"].dt.strftime("%Y-%m") == mon)
        iscon = (d["SOURCES"] == "TOL-CONNECT") & (d["_app"].dt.strftime("%Y-%m") == mon)
        d["_day"] = d["_reg"].where(d["SOURCES"] == "TOL-REGISTER", d["_app"])
        return d[isreg | iscon]

    curA = prep(cur_raw, month)
    prevA = prep(prev_raw, pmonth) if prev_raw is not None else curA.iloc[0:0]
    # per-shop TOL-CONNECT target (TARGET rows of the current file)
    curT = cur_raw[(cur_raw["ACTUAL_TYPE"] == "TARGET") & cur_raw["Shop Name"].map(lambda v: isinstance(v, str)) & (cur_raw["Shop Type"] != "Lotus's")].copy()
    for c in ["Region WW", "Shop Name", "Shop Type"]:
        curT[c] = curT[c].astype(str).str.strip()
    cur = cur_raw

    regions, types, pkgs, handlers, subs = {}, {}, {}, {}, {}
    shops, shop_idx = [], {}
    def ix(m, k):
        if k not in m: m[k] = len(m)
        return m[k]
    def shop_i(r):
        name = r["Shop Name"]
        if name not in shop_idx:
            shop_idx[name] = len(shops)
            shops.append([name, ix(regions, r["Region WW"]), ix(types, r["Shop Type"])])
        return shop_idx[name]
    def pack(df, mon):
        reg, con = [], []
        for _, r in df.iterrows():
            if r["SOURCES"] == "TOL-REGISTER":
                st = TOL_STATUS.index(r["SUBS_STATUS"]) if r["SUBS_STATUS"] in TOL_STATUS else 3
                reg.append([int(r["_day"].day), st, shop_i(r), ix(pkgs, r["PROMOTION_DESC"]), int(r["_app"].strftime("%Y-%m") == mon)])
            elif r["SOURCES"] == "TOL-CONNECT":
                con.append([int(r["_day"].day), shop_i(r), ix(pkgs, r["PROMOTION_DESC"])])
        return {"reg": reg, "con": con}
    out_cur, out_prev = pack(curA, month), pack(prevA, pmonth)
    todo = []
    for _, r in curA[(curA["SOURCES"] == "TOL-REGISTER") & (curA["SUBS_STATUS"] == "Pending")].iterrows():
        ap = pd.to_datetime(r["APPOINT_DAY"], errors="coerce")
        todo.append([(str(int(r["ASSET_NUM"])) if isinstance(r["ASSET_NUM"], (int, float)) else str(r["ASSET_NUM"])) if pd.notna(r["ASSET_NUM"]) else "", r["_reg"].strftime("%Y-%m-%d"),
                     ap.strftime("%Y-%m-%d") if pd.notna(ap) else "", shop_i(r), ix(pkgs, r["PROMOTION_DESC"]),
                     ix(handlers, (r["HANDLER"] if pd.notna(r["HANDLER"]) else "-")), ix(subs, (r["SUBCONTRACT"] if pd.notna(r["SUBCONTRACT"]) else "-"))])
    targets = {}
    for _, r in curT.iterrows():
        si = shop_i(r)
        targets[si] = targets.get(si, 0) + float(r["TARGET"] or 0)
    inv = lambda m: [k for k, _ in sorted(m.items(), key=lambda kv: kv[1])]
    res = {"month": month, "prevMonth": pmonth, "daysCur": int(last.days_in_month),
           "daysPrev": int((last.replace(day=1) - pd.Timedelta(days=1)).day), "asOf": last.strftime("%Y-%m-%d"),
           "regions": inv(regions), "types": inv(types), "shops": shops, "pkgs": inv(pkgs), "handlers": inv(handlers), "subs": inv(subs),
           "cur": out_cur, "prev": out_prev, "todo": todo, "targets": {str(k): v for k, v in targets.items()}}
    print(f"    TOL Regis & Connect: {month} as of {res['asOf']} | Register {len(out_cur['reg'])} (Connect {sum(1 for x in out_cur['reg'] if x[1]==0)}, Pending {sum(1 for x in out_cur['reg'] if x[1]==1)}, Cancel {sum(1 for x in out_cur['reg'] if x[1]==2)}, Un-Complete {sum(1 for x in out_cur['reg'] if x[1]==3)}) | TOL-CONNECT {len(out_cur['con'])} | Target {sum(targets.values()):,.0f} | prev {res['prevMonth']}: Register {len(out_prev['reg'])}, Connect {len(out_prev['con'])}")
    return res


def build(xlsx_path: str, out_path: str, shop_list_path: str = None, sheep_xlsx_path: str = None, contest_xlsx_path: str = None, retention_roster_path: str = None, sale_score_html_path: str = None, shop_reference_path: str = None, vivo_target_path: str = None, gt7_target_path: str = None, reno16_target_path: str = None, tmc_target_path: str = None, tmc_individual_path: str = None, extw_target_path: str = None, retmail_path: str = None, salesperf_path: str = None, awt_path: str = None, shopupd_path: str = None, tol_cur_path: str = None, tol_prev_path: str = None):
    df = pd.read_excel(xlsx_path, sheet_name="TSM")
    # Current month = November (xlsx_path). The prior month (October TSM, passed as shop_reference_path) feeds the
    # Trade In / Extended W. last-month comparison and the tabs that stay on October data (Huawei Watch GT7, Retention names).
    df_prev = pd.read_excel(shop_reference_path, sheet_name="TSM") if shop_reference_path and os.path.exists(shop_reference_path) else df

    handset_records, handset_f = export_group(df, "HANDSET", rev_col="PRICE")
    suplife_attach_records = export_suplife_attach(df)
    accessories_records, accessories_f = export_group(df, "ACCESSORIES", rev_col="PRICE")

    area_to_region = df.dropna(subset=["AREA"]).drop_duplicates(subset=["AREA"]).set_index("AREA")["REGION"].to_dict()
    # Some rows this month have a blank AREA/REGION (e.g. certain
    # accessory line items not yet tagged) -- sorting so non-null AREA
    # rows come first means drop_duplicates(keep="first") picks a row
    # with real area/region data for every shop that has one anywhere
    # in the sheet, instead of possibly locking in a blank.
    def _clean_shop_code(series):
        # A stray blank-SHOP_CODE row anywhere in a sheet forces the whole
        # column to float64 (e.g. 80100476 -> 80100476.0); concatenating a
        # float-typed column with an int-typed one from another file then
        # upcasts BOTH to float, silently breaking any string-keyed
        # lookup built from them. Route every SHOP_CODE through this
        # before use so "80100476" is always the key, never "80100476.0".
        return pd.to_numeric(series, errors="coerce").astype("Int64").astype(str)

    shop_cols = ["SHOP_CODE", "SHOP NAME", "TYPE SHOP", "REGION", "AREA"]
    shop_lookup_df = df[shop_cols].dropna(subset=["SHOP_CODE"]).copy()
    shop_lookup_df["SHOP_CODE"] = _clean_shop_code(shop_lookup_df["SHOP_CODE"])
    shop_lookup_df["_src_rank"] = 0  # current month's own rows take priority
    # Early in a new month, many shops haven't logged a single
    # transaction yet, so they're simply absent from this month's sheet
    # (shop_lookup.get() would return nothing at all, not just a blank
    # area/region). A shop's area/region/type doesn't change month to
    # month, so a prior month's file is a safe source to fill the gap
    # until the shop shows up in this month's own data.
    if shop_reference_path and os.path.exists(shop_reference_path):
        ref_df = pd.read_excel(shop_reference_path, sheet_name="TSM")[shop_cols].dropna(subset=["SHOP_CODE"]).copy()
        ref_df["SHOP_CODE"] = _clean_shop_code(ref_df["SHOP_CODE"])
        ref_df["_src_rank"] = 1
        shop_lookup_df = pd.concat([shop_lookup_df, ref_df], ignore_index=True)
    shop_lookup_df = shop_lookup_df.sort_values(by=["_src_rank", "AREA"], key=lambda s: s if s.name != "AREA" else s.isna())
    shop_lookup = {
        r["SHOP_CODE"]: {"shop": str(r["SHOP NAME"]).strip(), "type": r["TYPE SHOP"], "region": r["REGION"], "area": r["AREA"]}
        for _, r in shop_lookup_df.drop_duplicates(subset=["SHOP_CODE"]).iterrows()
    }

    if sheep_xlsx_path is None:
        default_sheep = os.path.join(os.path.dirname(os.path.abspath(xlsx_path)), "Sheep_Report.xlsx")
        sheep_xlsx_path = default_sheep if os.path.exists(default_sheep) else "Sheep_Report.xlsx"
    sheep_records, sheep_f = export_sheep(sheep_xlsx_path, area_to_region)

    if retention_roster_path is None:
        contest_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(contest_dir):
            if "retention" in fn.lower() or "staff_retention" in fn.lower():
                retention_roster_path = os.path.join(contest_dir, fn)
                break
    external_roster = load_retention_roster(retention_roster_path, shop_lookup)
    retchpn1_records, retchpn1_roster = export_emp_type(df, "Ret_chpn_1", external_roster=external_roster)

    if contest_xlsx_path is None:
        default_contest_glob = None
        contest_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(contest_dir):
            if "มงคล" in fn or "mongkol" in fn.lower():
                default_contest_glob = os.path.join(contest_dir, fn)
                break
        contest_xlsx_path = default_contest_glob
    mongkol_records, mongkol_data_as_of = export_mongkol(contest_xlsx_path, area_to_region)

    if gt7_target_path is None:
        gt7_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(gt7_dir):
            if "gt7" in fn.lower() and "target" in fn.lower():
                gt7_target_path = os.path.join(gt7_dir, fn)
                break
    # GT7 tab = October (prior-month TSM) followed by November (current TSM)
    _cur_start = pd.to_datetime(df["DATE"]).min().normalize().replace(day=1)
    df_gt7 = pd.concat([df_prev[pd.to_datetime(df_prev["DATE"]) < _cur_start], df], ignore_index=True) if df_prev is not df else df
    gt7_shop_records, gt7_daily, gt7_variants = export_huawei_watch_gt7(gt7_target_path, df_gt7, area_to_region)

    shop_ref_for_prev = shop_reference_path
    tradein = export_trade_in(df, shop_lookup, area_to_region, contest_xlsx_path, shop_reference_path)
    extw = export_extended_warranty(df, shop_lookup, area_to_region, contest_xlsx_path, shop_reference_path, extw_target_path)
    sl_data = export_service_level(awt_path, shopupd_path)
    tol_data = export_tol(tol_cur_path, tol_prev_path)
    sp = export_sale_performance(salesperf_path) if salesperf_path and os.path.exists(salesperf_path) else {"rows": [], "total": None, "year": "", "month": "", "day": 0, "source": ""}
    ret = export_retention(retmail_path, df_prev, contest_xlsx_path) if retmail_path and os.path.exists(retmail_path) else {"asOf": "", "products": RET_PRODUCTS, "shops": [], "staff": [], "source": ""}
    tmc = export_true_mobile_care(tmc_target_path, df, shop_lookup, area_to_region, contest_xlsx_path, tmc_individual_path)

    if sale_score_html_path is None:
        ss_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(ss_dir):
            if "sale_score" in fn.lower() or "salescore" in fn.lower() or "sale score" in fn.lower():
                sale_score_html_path = os.path.join(ss_dir, fn)
                break
    sale_score_html = export_sale_score_html(sale_score_html_path)

    HANDSET_ACC_FIELDS = ["date", "region", "area", "code", "shop", "type", "qty", "rev", "brand", "subBrand", "model", "subModel"]
    HANDSET_ACC_CATS = ["date", "region", "area", "code", "shop", "type", "brand", "subBrand", "model", "subModel"]
    handset_json = json.dumps(to_dict_encoded(handset_records, HANDSET_ACC_FIELDS, HANDSET_ACC_CATS), ensure_ascii=False)
    accessories_json = json.dumps(to_dict_encoded(accessories_records, HANDSET_ACC_FIELDS, HANDSET_ACC_CATS), ensure_ascii=False)
    sheep_json = json.dumps(sheep_records, ensure_ascii=False)
    shops_json = load_shops_master(shop_list_path, df)
    targets_json = json.dumps(ENTRY_MODEL_TARGETS, ensure_ascii=False)
    retchpn1_json = json.dumps(retchpn1_records, ensure_ascii=False)
    retchpn1_roster_json = json.dumps(retchpn1_roster, ensure_ascii=False)
    mongkol_json = json.dumps(mongkol_records, ensure_ascii=False)
    sale_score_html_json = json.dumps(sale_score_html, ensure_ascii=False)
    # The embedded page has its own <script> tags -- without escaping,
    # the HTML PARSER (not the JS engine) would see a literal "</script>"
    # inside this JSON string and close our outer <script> block early,
    # corrupting everything after it. Escaping the slash keeps the JSON
    # string valid while making it invisible to the HTML parser.
    sale_score_html_json = re.sub(r"</(script)", r"<\\/\1", sale_score_html_json, flags=re.IGNORECASE)

    SUPLIFE_FIELDS = ["date", "region", "area", "code", "shop", "type", "saleCode", "saleName", "empType", "suplife", "suplifeNetAmount", "iphone"]
    SUPLIFE_CATS = ["date", "region", "area", "code", "shop", "type", "saleCode", "saleName", "empType"]
    suplife_attach_json = json.dumps(to_dict_encoded(suplife_attach_records, SUPLIFE_FIELDS, SUPLIFE_CATS), ensure_ascii=False)

    gt7_shops_json = json.dumps(gt7_shop_records, ensure_ascii=False)
    gt7_daily_json = json.dumps(gt7_daily, ensure_ascii=False)
    gt7_variants_json = json.dumps(gt7_variants, ensure_ascii=False)

    html = (
        TEMPLATE
        .replace("__CSS__", CSS)
        .replace("__BODY__", BODY)
        .replace("__HANDSET_DATA__", handset_json)
        .replace("__ACCESSORIES_DATA__", accessories_json)
        .replace("__SHEEP_DATA__", sheep_json)
        .replace("__SHOPS__", shops_json)
        .replace("__ENTRY_MODEL_TARGETS__", targets_json)
        .replace("__ENTRY_MODEL_MONTH_DAYS__", json.dumps(ENTRY_MODEL_MONTH_DAYS))
        .replace("__ENTRY_MODEL_MONTH_LABEL__", json.dumps(ENTRY_MODEL_MONTH_LABEL))
        .replace("__RETCHPN1_DATA__", retchpn1_json)
        .replace("__RETCHPN1_ROSTER__", retchpn1_roster_json)
        .replace("__MONGKOL_DATA__", mongkol_json)
        .replace("__MONGKOL_DATA_AS_OF__", json.dumps(mongkol_data_as_of))
        .replace("__SALE_SCORE_HTML__", sale_score_html_json)
        .replace("__SUPLIFE_ATTACH_DATA__", suplife_attach_json)
        .replace("__TRADEIN_DATA__", json.dumps(tradein, ensure_ascii=False, separators=(",", ":")))
        .replace("__EXTW_DATA__", json.dumps(extw, ensure_ascii=False, separators=(",", ":")))
        .replace("__TOL_DATA__", json.dumps(tol_data, ensure_ascii=False, separators=(",", ":")))
        .replace("__SL_DATA__", json.dumps(sl_data, ensure_ascii=False, separators=(",", ":")))
        .replace("__RET_DATA__", json.dumps(ret, ensure_ascii=False, separators=(",", ":")))
        .replace("__SP_DATA__", json.dumps(sp, ensure_ascii=False, separators=(",", ":")))
        .replace("__TMC_DATA__", json.dumps(tmc, ensure_ascii=False))
        .replace("__GT7_SHOPS__", gt7_shops_json)
        .replace("__GT7_DAILY__", gt7_daily_json)
        .replace("__GT7_VARIANTS__", gt7_variants_json)
        .replace("__JS__", JS)
    )
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write(html)

    n_shops_master = len(json.loads(shops_json))
    type_shop_counts = df["TYPE SHOP"].value_counts().to_dict()

    handset_f_all = df[df["CUSTOM_PRODGROUP"] == "HANDSET"]
    entry_actuals = []
    for t in ENTRY_MODEL_TARGETS:
        if t.get("match"):
            nm = handset_f_all["CUSTOM_MODEL"].astype(str).str.upper() + " " + handset_f_all["CUSTOM_SUBMODEL"].astype(str).str.upper()
            qty = handset_f_all[(handset_f_all["CUSTOM_BRAND"].astype(str).str.upper() == t["brand"]) & nm.str.contains(t["match"], regex=False)]["QTY"].sum()
        else:
            qty = handset_f_all[(handset_f_all["CUSTOM_BRAND"] == t["brand"]) & (handset_f_all["CUSTOM_SUBMODEL"] == t["subModel"])]["QTY"].sum()
        entry_actuals.append((t["label"], int(qty), t["target"]))

    print(f"OK -> {out_path}")
    print(f"    Handset:     {len(handset_records)} rows | {handset_f['QTY'].sum():,} units | {handset_f['PRICE'].sum():,} THB (Price)")
    print(f"    Accessories: {len(accessories_records)} rows | {accessories_f['QTY'].sum():,} units | {accessories_f['PRICE'].sum():,} THB (Price)")
    if sheep_f is not None:
        print(f"    Sheep:       {len(sheep_records)} rows | {sheep_f['QTY'].sum():,.0f} units | {sheep_f['NET_AMOUNT'].sum():,.2f} THB  (from {sheep_xlsx_path})")
    else:
        print(f"    Sheep:       0 rows -- {sheep_xlsx_path} not found, Sheep page will show 0s")
    print(f"    Shop master list: {n_shops_master} shops ({'from file' if shop_list_path else 'derived from TSM sheet'})")
    print(f"    TYPE SHOP breakdown (all included): {type_shop_counts}")
    print(f"    Ret_chpn_1: {len(retchpn1_records)} handset rows | {len(retchpn1_roster)} employees in roster ({'from List_Staff_Retention.xlsx' if external_roster else 'derived from TSM sheet'})")
    print(f"    Entry Model vs Target ({ENTRY_MODEL_MONTH_LABEL}):")
    total_actual = sum(a for _, a, _ in entry_actuals)
    total_target = sum(t for _, _, t in entry_actuals)
    for label, actual, target in entry_actuals:
        pct = (actual / target * 100) if target else 0
        print(f"      {label:<20} {actual:>6,} / {target:>6,}  ({pct:5.1f}%)")
    print(f"      {'TOTAL':<20} {total_actual:>6,} / {total_target:>6,}  ({total_actual/total_target*100:5.1f}%)")
    if mongkol_records:
        top = max(r["octActual"] for r in mongkol_records)
        print(f"    Mongkol Number contest (Oct): {len(mongkol_records)} participants | data as of {mongkol_data_as_of} | top score {top}")
    else:
        print(f"    Mongkol Number contest: 0 participants -- roster file not found, tab will show 0s")
    if sale_score_html:
        print(f"    Sale Score Leaderboard: embedded ({len(sale_score_html):,} chars) -- now the first tab")
    else:
        print(f"    Sale Score Leaderboard: not found -- tab will show a blank/empty iframe")
    total_suplife = sum(r["suplife"] for r in suplife_attach_records)
    total_iphone = sum(r["iphone"] for r in suplife_attach_records)
    print(f"    Attach Suplife PLV: {total_suplife:,} SUPLIFE / {total_iphone:,} iPhone ({total_suplife/total_iphone*100 if total_iphone else 0:.1f}%) | {len(set(r['saleName'] for r in suplife_attach_records)):,} salespeople")
    if gt7_shop_records:
        gt7_total_target = sum(r["target"] for r in gt7_shop_records)
        gt7_total_actual = sum(r["actual"] for r in gt7_shop_records)
        n_with_target = sum(1 for r in gt7_shop_records if r["target"] > 0)
        print(f"    Huawei Watch GT7: {len(gt7_shop_records)} shops ({n_with_target} with a target) | {gt7_total_actual:,} / {gt7_total_target:,.0f} units ({gt7_total_actual/gt7_total_target*100 if gt7_total_target else 0:.1f}%)")
        by_model = {}
        for v in gt7_variants:
            by_model[v["model"]] = by_model.get(v["model"], 0) + v["qty"]
        print(f"      by model: " + " | ".join(f"{m}: {q:,}" for m, q in sorted(by_model.items())) + f" | {len(set((v['model'], v['size'], v['color']) for v in gt7_variants))} size/colour variants")
    else:
        print(f"    Huawei Watch GT7: 0 shops -- target file not found, tab will show 0s")

if __name__ == "__main__":
    xlsx_path = sys.argv[1] if len(sys.argv) > 1 else "Refresh_TSM.xlsx"
    out_path = sys.argv[2] if len(sys.argv) > 2 else "Handset_Sales_Dashboard.html"
    shop_list_path = sys.argv[3] if len(sys.argv) > 3 and sys.argv[3] else None
    sheep_xlsx_path = sys.argv[4] if len(sys.argv) > 4 and sys.argv[4] else None
    contest_xlsx_path = sys.argv[5] if len(sys.argv) > 5 and sys.argv[5] else None
    retention_roster_path = sys.argv[6] if len(sys.argv) > 6 and sys.argv[6] else None
    sale_score_html_path = sys.argv[7] if len(sys.argv) > 7 and sys.argv[7] else None
    shop_reference_path = sys.argv[8] if len(sys.argv) > 8 and sys.argv[8] else None
    vivo_target_path = sys.argv[9] if len(sys.argv) > 9 and sys.argv[9] else None
    gt7_target_path = sys.argv[10] if len(sys.argv) > 10 and sys.argv[10] else None
    reno16_target_path = sys.argv[11] if len(sys.argv) > 11 and sys.argv[11] else None
    tmc_target_path = sys.argv[12] if len(sys.argv) > 12 and sys.argv[12] else None
    tmc_individual_path = sys.argv[13] if len(sys.argv) > 13 and sys.argv[13] else None
    extw_target_path = sys.argv[14] if len(sys.argv) > 14 and sys.argv[14] else None
    retmail_path = sys.argv[15] if len(sys.argv) > 15 and sys.argv[15] else None
    salesperf_path = sys.argv[16] if len(sys.argv) > 16 and sys.argv[16] else None
    awt_path = sys.argv[17] if len(sys.argv) > 17 and sys.argv[17] else None
    shopupd_path = sys.argv[18] if len(sys.argv) > 18 and sys.argv[18] else None
    tol_cur_path = sys.argv[19] if len(sys.argv) > 19 and sys.argv[19] else None
    tol_prev_path = sys.argv[20] if len(sys.argv) > 20 and sys.argv[20] else None
    build(xlsx_path, out_path, shop_list_path, sheep_xlsx_path, contest_xlsx_path, retention_roster_path, sale_score_html_path, shop_reference_path, vivo_target_path, gt7_target_path, reno16_target_path, tmc_target_path, tmc_individual_path, extw_target_path, retmail_path, salesperf_path, awt_path, shopupd_path, tol_cur_path, tol_prev_path)
